style.css:
@-moz-document domain("youtube.com") {
body {
    background: url("data:image/jpeg;base64, ...your big base64 block...") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Add dark overlay tint */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.4); /* adjust darkness (0.4 = 40% black) */
    pointer-events: none;
    z-index: 0;
  }

  /* Keep YouTube content above background */
  #content, #page-manager, ytd-app {
    background: transparent !important;
    position: relative;
    z-index: 1;
  }

  /* ? Make top bar transparent */
  ytd-masthead,
  #masthead-container,
  #masthead {
    background: transparent !important;
    box-shadow: none !important;
  }
}
